package cn.bidcheck.verification.facts;

import cn.bidcheck.domain.Domain.*;
import cn.bidcheck.persistence.Store;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.facts.LedgerValues.*;

class FactLedgerServiceTest {
    final MemoryStore store=new MemoryStore();final FactLedgerService ledger=new FactLedgerService(store);
    Document doc(String id,String text){return new Document(id,"project","BID",id+".pdf",1,"a".repeat(64),"",List.of(new Page(1,text,"PAGE","PDFBOX_NATIVE","")),List.of());}
    Map<String,Object> source(Document d,String id){return of("id",id,"projectId",d.projectId(),"evidence",new Evidence(d.id(),d.name(),1,"PAGE",d.pages().get(0).text(),"chars:0",1),"documentHash",d.sha256(),"documentVersion",d.version(),"parserFingerprint",FactLedgerService.parserFingerprint(d.pages().get(0)));}
    Map<String,Object> fact(String id,String value,String source){return of("id",id,"kind","FIELD","subject","合成甲","field","category","rawValue",value,"value",value,"unit","","basis","","scope","CURRENT_PROJECT","sourceIds",List.of(source),"attributes",Map.of());}
    Map<String,Object> batch(List<Map<String,Object>> facts,List<Map<String,Object>> sources){return of("facts",facts,"sources",sources,"engineVersion","engine-v1","operationIdentity","extract-test");}
    Map<String,Object> publish(String run,String cp,List<Document> docs,Map<String,Object> b){return ledger.publish("project",run,cp,"engine-identity",docs,b);}
    List<Map<String,Object>> lookup(List<Document> docs){return ledger.lookup("project","engine-identity",docs,Map.of());}
    Map<String,Object> view(String run,List<Document> docs){return ledger.view("project",run,"engine-identity",docs);}
    Map<String,Object> fieldReceipt(String field,String status,List<String> factIds){Map<String,Object> target=of("predicate","FIELD","subject","合成甲","field",field,"unit","","parameters",Map.of(),"targetExpected","","children",List.of());return of("observationKey",FieldCoverage.key(target),"target",target,"status",status,"sourceIds",List.of("S"),"factIds",factIds,"sourceScopeComplete",Set.of("EXTRACTED","READ_NOT_FOUND").contains(status),"observationPolicy",FieldCoverage.POLICY,"modelIdentity","model");}
    @Test void independentFieldReceiptsSurviveUnrelatedInvalidFact(){
        Document d=doc("d","合成甲 类别：一级");Map<String,Object> good=fact("good","一级","S"),bad=fact("bad","虚构","S");bad.put("field","employer");Map<String,Object> b=batch(List.of(good,bad),List.of(source(d,"S")));
        b.put("fieldCoverage",List.of(fieldReceipt("category","EXTRACTED",List.of("good")),fieldReceipt("employer","FAILED",List.of())));b.put("observationPolicy",FieldCoverage.POLICY);
        var receipt=publish("run","cp",List.of(d),b);assertEquals(1,receipt.get("accepted"));assertEquals(1,maps(receipt.get("rejected")).size());assertEquals(2,maps(receipt.get("fieldCoverage")).size());
        var values=ledger.lookup("project","engine-identity",List.of(d),Map.of("includeFieldCoverage",true));assertEquals(1,values.size());assertEquals(2,maps(values.get(0).get("fieldCoverage")).size());assertEquals(2,maps(view("run",List.of(d)).get("fieldCoverage")).size());
    }
    @Test void emptyFactBatchesRetainUnreadReadNotFoundAndFailedSeparately(){
        Document d=doc("d","合成甲 类别：一级");for(String status:List.of("UNREAD","READ_NOT_FOUND","FAILED")){Map<String,Object> b=batch(List.of(),List.of(source(d,"S")));b.put("fieldCoverage",List.of(fieldReceipt("category",status,List.of())));assertEquals(true,publish("run",status,List.of(d),b).get("coveragePublished"));}
        assertTrue(lookup(List.of(d)).isEmpty(),"legacy fact lookup does not invent pseudo facts");var rows=ledger.lookup("project","engine-identity",List.of(d),Map.of("includeFieldCoverage",true));assertEquals(3,rows.size());assertTrue(rows.stream().allMatch(row->"FIELD_COVERAGE".equals(row.get("recordType"))));
        assertEquals(Set.of("UNREAD","READ_NOT_FOUND","FAILED"),maps(view("run",List.of(d)).get("fieldCoverage")).stream().map(row->row.get("status")).collect(java.util.stream.Collectors.toSet()));assertTrue(rows.stream().flatMap(row->maps(row.get("fieldCoverage")).stream()).allMatch(row->Boolean.FALSE.equals(row.get("absenceProven"))));
    }
    @Test void fieldReceiptCannotClaimMissingFactOrUnreturnedSource(){
        Document d=doc("d","合成甲 类别：一级");Map<String,Object> b=batch(List.of(fact("f","一级","S")),List.of(source(d,"S")));b.put("fieldCoverage",List.of(fieldReceipt("category","EXTRACTED",List.of("missing"))));assertTrue(maps(publish("run","cp",List.of(d),b).get("fieldCoverage")).isEmpty());
        var receipt=fieldReceipt("category","READ_NOT_FOUND",List.of());receipt.put("sourceIds",List.of("other"));b.put("fieldCoverage",List.of(receipt));assertTrue(maps(publish("run","cp2",List.of(d),b).get("fieldCoverage")).isEmpty());
    }
    @Test void readNotFoundNeedsCompletedSourceReadAndMatchingParser(){
        Document d=doc("d","合成甲 类别：一级");var receipt=fieldReceipt("category","READ_NOT_FOUND",List.of());receipt.put("sourceScopeComplete",false);var b=batch(List.of(),List.of(source(d,"S")));b.put("fieldCoverage",List.of(receipt));assertEquals(false,publish("run","cp",List.of(d),b).get("coveragePublished"));
        receipt.put("sourceScopeComplete",true);publish("run","cp2",List.of(d),b);Document changed=new Document(d.id(),d.projectId(),d.role(),d.name(),d.version(),d.sha256(),"",List.of(new Page(1,d.pages().get(0).text(),"PAGE","NEW_PARSER","")),List.of());assertTrue(ledger.lookup("project","engine-identity",List.of(changed),Map.of("includeFieldCoverage",true)).isEmpty());
    }
    @Test void pendingCoverageRowsCannotCrowdValidatedFactsOutOfLookupLimit(){Document d=doc("d","合成甲 类别：一级");var empty=batch(List.of(),List.of(source(d,"S")));empty.put("fieldCoverage",List.of(fieldReceipt("category","UNREAD",List.of())));publish("run","pending",List.of(d),empty);publish("run","done",List.of(d),batch(List.of(fact("f","一级","S")),List.of(source(d,"S"))));var rows=ledger.lookup("project","engine-identity",List.of(d),Map.of("limit",1,"includeFieldCoverage",true));assertEquals(1,rows.size());assertTrue(rows.get(0).containsKey("fact"));}
    @Test void realSourcesAreReturnedWithDependencyOrigins(){Document d=doc("d","合成甲 类别：一级");var b=batch(List.of(fact("model-id","一级","S1")),List.of(source(d,"S1")));assertEquals(1,publish("run","cp",List.of(d),b).get("accepted"));var result=lookup(List.of(d));assertEquals(1,result.size());assertEquals("一级",map(result.get(0).get("fact")).get("rawValue"));assertEquals("cp",maps(result.get(0).get("origins")).get(0).get("checkpointId"));assertFalse(store.readParents.stream().anyMatch(Objects::isNull));}
    @Test void graphSelectedOccurrenceMustStillMatchTheCurrentManifestExactly(){
        Document d=doc("d","合成甲 类别：一级");var receipt=publish("run","cp",List.of(d),batch(List.of(fact("f","一级","S")),List.of(source(d,"S"))));
        String occurrenceId=String.valueOf(((List<?>)receipt.get("occurrenceIds")).get(0));
        var accepted=ledger.revalidateOccurrences("project",List.of(occurrenceId),List.of(d));
        assertEquals(1,accepted.size());assertEquals(true,accepted.get(0).get("revalidatedForCurrentManifest"));
        Document reparsed=new Document(d.id(),d.projectId(),d.role(),d.name(),d.version(),d.sha256(),"",List.of(new Page(1,d.pages().get(0).text(),"PAGE","NEW_PARSER","")),List.of());
        assertTrue(ledger.revalidateOccurrences("project",List.of(occurrenceId),List.of(reparsed)).isEmpty());
        Document foreign=new Document(d.id(),"other",d.role(),d.name(),d.version(),d.sha256(),"",d.pages(),List.of());
        assertThrows(IllegalArgumentException.class,()->ledger.revalidateOccurrences("project",List.of(occurrenceId),List.of(foreign)));
    }
    @Test void projectConfigurationAndManifestVersionsAreIsolated(){Document d=doc("d","合成甲：一级");publish("run","cp",List.of(d),batch(List.of(fact("f","一级","S")),List.of(source(d,"S"))));assertEquals(List.of(),ledger.lookup("project","different-engine",List.of(d),Map.of()));Document newer=new Document(d.id(),d.projectId(),d.role(),d.name(),2,d.sha256(),"",d.pages(),List.of());assertEquals(List.of(),lookup(List.of(newer)));Document foreign=new Document("foreign","other","BID","",1,d.sha256(),"",d.pages(),List.of());assertEquals(List.of(),ledger.lookup("other","engine-identity",List.of(foreign),Map.of()));assertThrows(IllegalArgumentException.class,()->ledger.lookup("other","engine-identity",List.of(d),Map.of()));assertThrows(IllegalArgumentException.class,()->ledger.lookup("project","engine-identity",List.of(d),Map.of("documentIds",List.of("foreign"))));}
    @Test void parserChangesInvalidateEvenWhenOriginalBinaryHashIsUnchanged(){Document d=doc("d","合成甲：一级");publish("run","cp",List.of(d),batch(List.of(fact("f","一级","S")),List.of(source(d,"S"))));Document reparsed=new Document(d.id(),d.projectId(),d.role(),d.name(),d.version(),d.sha256(),"",List.of(new Page(1,d.pages().get(0).text(),"PAGE","PDFBOX_OCR","")),List.of());assertTrue(lookup(List.of(reparsed)).isEmpty());}
    @Test void duplicatesNeverOverwriteRawValuesAndCheckpointsShareOccurrence(){Document d=doc("d","合成甲：一级");var f=fact("first-model-id","一级","S");var b=batch(List.of(f),List.of(source(d,"S")));var first=publish("run","cp1",List.of(d),b);var retry=publish("run","cp1",List.of(d),b);assertEquals(first.get("occurrenceIds"),retry.get("occurrenceIds"));assertEquals(1,retry.get("reused"));assertEquals(1,maps(view("run",List.of(d)).get("dependencies")).size());f.put("id","different-model-id");publish("run","cp2",List.of(d),batch(List.of(f),List.of(source(d,"S"))));var current=view("run",List.of(d));assertEquals(1,map(current.get("summary")).get("occurrences"));assertEquals(1L,map(current.get("summary")).get("sharedOccurrences"));assertEquals("first-model-id",map(maps(current.get("occurrences")).get(0).get("fact")).get("id"));}
    @Test void inventedQuoteOrHashCannotEnterLedger(){Document d=doc("d","合成甲：一级");var s=source(d,"S");s.put("evidence",new Evidence(d.id(),d.name(),1,"PAGE","虚构二级","",1));assertEquals(0,publish("run","cp",List.of(d),batch(List.of(fact("f","二级","S")),List.of(s))).get("accepted"));s=source(d,"S");s.put("documentHash","b".repeat(64));assertEquals(0,publish("run2","cp",List.of(d),batch(List.of(fact("f","一级","S")),List.of(s))).get("accepted"));assertTrue(lookup(List.of(d)).isEmpty());}
    Map<String,Object> certificate(String id,String code,String grade,String source){var f=fact(id,grade,source);f.put("kind","CERTIFICATE");f.put("attributes",of("number",code,"numberField","注册编号","category","合成资格证","referenceDate","2030-01-01"));return f;}
    @Test void sameNameDifferentCertificateNumbersNeverMerge(){Document a=doc("a","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-A 类别一级"),b=doc("b","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-B 类别二级");publish("run","cp",List.of(a,b),batch(List.of(certificate("a","CERT-A","一级","A"),certificate("b","CERT-B","二级","B")),List.of(source(a,"A"),source(b,"B"))));var out=view("run",List.of(a,b));assertEquals(2,maps(out.get("entities")).size());assertTrue(maps(out.get("entities")).stream().allMatch(e->"STRONG".equals(e.get("identityStrength"))));assertEquals(0,maps(out.get("conflicts")).size());}
    @Test void sameStrongIdentityAndComparableFieldRetainBothConflictingOccurrences(){Document a=doc("a","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-A 类别一级"),b=doc("b","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-A 类别二级");publish("run","cp",List.of(a,b),batch(List.of(certificate("a","CERT-A","一级","A"),certificate("b","CERT-A","二级","B")),List.of(source(a,"A"),source(b,"B"))));var out=view("run",List.of(a,b));assertEquals(2,maps(out.get("occurrences")).size());assertEquals(1,maps(out.get("entities")).size());assertEquals(1,maps(out.get("conflicts")).size());}
    @Test void mereNamesOrDifferentTaxBasisNeverBecomeConflicts(){Document a=doc("a","合成甲 一级"),b=doc("b","合成甲 二级");publish("run","cp",List.of(a,b),batch(List.of(fact("a","一级","A"),fact("b","二级","B")),List.of(source(a,"A"),source(b,"B"))));assertEquals(2,maps(view("run",List.of(a,b)).get("entities")).size());assertTrue(maps(view("run",List.of(a,b)).get("conflicts")).isEmpty());}
    @Test void identifierOnDifferentPersonRowCannotPromoteNameOnlyEntity(){Document d=doc("d","合成甲：一级\n合成乙 身份证号：110101199001010010");var f=fact("f","一级","S");f.put("attributes",Map.of("entityType","PERSON"));publish("run","cp",List.of(d),batch(List.of(f),List.of(source(d,"S"))));assertEquals("SOURCE_LOCAL",maps(view("run",List.of(d)).get("entities")).get(0).get("identityStrength"));}
    @Test void sensitiveIdentifiersAreMaskedOutsideOriginalSource(){Document d=doc("d","合成甲 身份证号：110101199001010010 类别一级");var f=fact("f","一级","S");f.put("attributes",Map.of("entityType","PERSON"));publish("run","cp",List.of(d),batch(List.of(f),List.of(source(d,"S"))));var e=maps(view("run",List.of(d)).get("entities")).get(0);assertEquals("STRONG",e.get("identityStrength"));assertFalse(canonical(e.get("identifiers")).contains("110101199001010010"));assertTrue(canonical(e.get("sourceRefs")).contains("110101199001010010"));}
    @Test void frozenRunCannotLeakFactsOrDependenciesPublishedByLaterRuns(){Document d=doc("d","合成甲：一级、二级");var docs=List.of(d);publish("old","cp",docs,batch(List.of(fact("f1","一级","S")),List.of(source(d,"S"))));var frozen=ledger.snapshot("project","old","engine-identity",docs);publish("new","cp2",docs,batch(List.of(fact("f2","二级","S")),List.of(source(d,"S"))));assertEquals(frozen,ledger.snapshot("project","old","engine-identity",docs));assertEquals(frozen,view("old",docs));assertEquals(1,maps(view("new",docs).get("occurrences")).size());assertThrows(IllegalStateException.class,()->publish("old","cp3",docs,batch(List.of(fact("f3","二级","S")),List.of(source(d,"S")))));}
    @Test void coverageIsAvailableOnlyForAnEntireRevalidatedBatch(){Document d=doc("d","合成甲：一级、二级");var b=batch(List.of(fact("a","一级","S"),fact("b","二级","S")),List.of(source(d,"S")));b.put("extractionCoverage",of("status","VALIDATED","modelIdentity","m1","ruleSignatures",List.of("r1"),"sourceIds",List.of("S"),"factIds",List.of("a","b")));assertEquals(true,publish("run","cp",List.of(d),b).get("coveragePublished"));assertTrue(lookup(List.of(d)).stream().allMatch(e->e.containsKey("extractionCoverage")));var limited=ledger.lookup("project","engine-identity",List.of(d),Map.of("limit",1));assertEquals(1,limited.size());assertFalse(limited.get(0).containsKey("extractionCoverage"));assertEquals(false,limited.get(0).get("coverageComplete"));}

    @Test void identityEnvelopeAndUiFieldsRetainSourceConfidence(){Document d=doc("d","合成甲 身份证号：110101199001010010 类别一级");var f=fact("f","一级","S");f.put("attributes",Map.of("entityType","PERSON"));publish("run","cp",List.of(d),batch(List.of(f),List.of(source(d,"S"))));var result=lookup(List.of(d)).get(0);assertEquals("STRONG",result.get("identityStrength"));assertEquals("PERSON",result.get("entityType"));assertFalse(canonical(result.get("identityClaims")).contains("110101199001010010"));assertEquals(1.0,map(maps(result.get("sources")).get(0).get("evidence")).get("confidence"));var row=maps(view("run",List.of(d)).get("occurrences")).get(0);assertEquals("FIELD",row.get("kind"));assertEquals(result.get("entityId"),row.get("entityId"));}
    @Test void ungroundedTimeAndDifferentTaxBasisDoNotAssertConflict(){Document a=doc("a","合成甲 合成资格证 注册编号 CERT-A 类别一级"),b=doc("b","合成甲 合成资格证 注册编号 CERT-A 类别二级");publish("run","cp",List.of(a,b),batch(List.of(certificate("a","CERT-A","一级","A"),certificate("b","CERT-A","二级","B")),List.of(source(a,"A"),source(b,"B"))));assertTrue(maps(view("run",List.of(a,b)).get("conflicts")).isEmpty());
        a=doc("tax-a","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-A 类别一级");b=doc("tax-b","截至2030-01-01，合成甲 合成资格证 注册编号 CERT-A 类别二级");var first=certificate("a","CERT-A","一级","A");var second=certificate("b","CERT-A","二级","B");var attrs=map(second.get("attributes"));attrs.put("taxBasis","EXCLUDING_TAX");second.put("attributes",attrs);publish("tax-run","cp",List.of(a,b),batch(List.of(first,second),List.of(source(a,"A"),source(b,"B"))));assertTrue(maps(view("tax-run",List.of(a,b)).get("conflicts")).isEmpty());}
    @Test void malformedRowsCannotSilentlyPublishAnExtractionReceipt(){Document d=doc("d","合成甲 一级");var b=batch(List.of(fact("f","一级","S")),List.of(source(d,"S")));b.put("facts",List.of(fact("f","一级","S"),"not-a-fact"));assertThrows(IllegalArgumentException.class,()->publish("run","cp",List.of(d),b));assertTrue(store.rows.isEmpty());}
    @Test void purePersonIdentityRetainsConflictingHashesWithoutMerging(){var sources=List.of(of("id","A","sourceFingerprint","a","evidence",Map.of("quote","合成人 身份证号：110101199001010010")),of("id","B","sourceFingerprint","b","evidence",Map.of("quote","合成人 身份证号：110101199001010029")));var entity=EntityIdentity.resolvePerson("合成人",sources);assertEquals("SOURCE_LOCAL",entity.get("identityStrength"));assertEquals(2,maps(entity.get("identityClaims")).stream().map(c->c.get("valueFingerprint")).distinct().count());assertFalse(canonical(entity).contains("110101199001010010"));}

    @Test void contactIdentifierOnSameLineCannotBeAssignedToProjectManager(){var sources=List.of(of("id","S","evidence",Map.of("quote","项目经理：合成甲，联系人：合成乙，身份证号：110101199001010010")));assertEquals("SOURCE_LOCAL",EntityIdentity.resolvePerson("合成甲",sources).get("identityStrength"));assertEquals("STRONG",EntityIdentity.resolvePerson("合成乙",sources).get("identityStrength"));assertEquals("SOURCE_LOCAL",EntityIdentity.resolvePerson("合成甲",List.of(of("id","S","evidence",Map.of("quote","合成甲、合成乙 身份证号：110101199001010010")))).get("identityStrength"));}
    @Test void directNameFieldWithCommaCanBindAndSourceLocalIdsStaySeparate(){var a=List.of(of("id","A","evidence",Map.of("quote","姓名：合成甲，身份证号：110101199001010010")));assertEquals("STRONG",EntityIdentity.resolvePerson("合成甲",a).get("identityStrength"));assertNotEquals(EntityIdentity.resolvePerson("合成甲",List.of(of("id","A","evidence",Map.of("quote","姓名：合成甲")))).get("id"),EntityIdentity.resolvePerson("合成甲",List.of(of("id","B","evidence",Map.of("quote","姓名：合成甲")))).get("id"));}

    static final class MemoryStore extends Store {
        record Row(String kind,String project,String parent,Map<String,Object> value){}
        final Map<String,Row> rows=new LinkedHashMap<>();final List<String> readParents=new ArrayList<>();MemoryStore(){super(null,new ObjectMapper());}
        @Override public void save(String kind,String id,String project,String parent,Object value){assertTrue(id.length()<=64,"DB id length");assertTrue(parent==null||parent.length()<=64,"DB parent length");rows.put(id,new Row(kind,project,parent,LedgerValues.map(json.convertValue(value,Map.class))));}
        @Override public Map<String,Object> getMap(String kind,String id){Row row=rows.get(id);if(row==null||!kind.equals(row.kind))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return copy(row.value);}
        @Override public List<Map<String,Object>> maps(String kind,String project,String parent){readParents.add(parent);return rows.values().stream().filter(r->kind.equals(r.kind)&&(project==null||project.equals(r.project))&&(parent==null||parent.equals(r.parent))).map(r->copy(r.value)).toList();}
    }
}
